import {readFile,writeFile} from 'node:fs/promises';
import {analyzeMicrodata,validateMicrodata} from '../assets/microdata.mjs';
import {nationalVotes} from '../assets/electoral.mjs';
const load=async name=>JSON.parse(await readFile(new URL('../'+name,import.meta.url),'utf8'));
const data=validateMicrodata(await load('calibration/microdata-3411.json')),official=await load('data/official-2023.json');
const actual=nationalVotes(official.provinces),valid=actual.total+official.provinces.reduce((s,p)=>s+p.blankVotes,0),ids=['pp','psoe','vox','sumar'];
const methods=[['Pesos iguales',{basis:'equal'}],['PESO publicado',{}],['PESO × participación declarada',{participation:'declared'}],['PESO + recuerdo 2019',{recallStrength:1}],['PESO + recuerdo 2019 + indecisos por recuerdo',{recallStrength:1,undecided:'recall'}]];
const rows=methods.map(([name,options])=>{const result=analyzeMicrodata(data,{...options,dimension:'total',reference:data.reference}),values=Object.fromEntries(ids.map(id=>[id,result.national.validPercent[id]||0])),errors=ids.map(id=>Math.abs(values[id]-100*actual.totals[id]/valid));return {name,options,values,mae:errors.reduce((a,b)=>a+b)/errors.length,effectiveN:result.effectiveN};});
const output={schemaVersion:1,study:'3411',sample:data.sample,fieldworkStart:'2023-06-08',fieldworkEnd:'2023-06-27',election:'2023-07-23',referenceElection:'2019-11-10',reference:data.reference,referenceSource:'https://infoelectoral.interior.gob.es/estaticos/docxl/PROV_02_201911_1.zip',sourceUrl:data.sourceUrl,technicalUrl:data.technicalUrl,sha256:data.sha256,actualSource:official.source,actual:Object.fromEntries(ids.map(id=>[id,100*actual.totals[id]/valid])),rows,note:'Comprobación retrospectiva de una elección. Las reglas no se han optimizado para minimizar este error, pero se diseñan con los resultados históricos ya conocidos: no es una validación prospectiva ni acredita superioridad. MAE solo sobre PP, PSOE, Vox y Sumar, con denominador voto válido incluido blanco. El recuerdo utiliza 2019, no el resultado de 2023 que se compara. Falta evaluar varias elecciones reservadas y otros contextos.'};
await writeFile(new URL('../data/microdata-validation.json',import.meta.url),JSON.stringify(output,null,2));console.log(rows.map(r=>r.name+': MAE '+r.mae.toFixed(3)).join('\n'));
